// Exports the exact PCM generated by Unity tests. No external audio or tools.
const fs = require('fs'), path = require('path'), crypto = require('crypto');
const root = path.resolve(__dirname, '../..');
const source = path.join(root, 'TestResults/arcade_audio');
const target = path.join(root, '音声確認/現在ゲームで使用中');
const cues = ['通常ヒット','特殊ヒット','ガード','ジャスト','カウンター','ブレイク','三段目ヒット','超必殺発動','KO','場外','カウント','メニュー移動','決定','戻る','舞台縮小','紙の風切り','FIGHT','TIME_UP','リザルト'];
const ids = ['NormalHit','SpecialHit','Guard','Just','Counter','Break','ComboFinish','Ultimate','KO','RingOut','Countdown','Move','Confirm','Cancel','Shrink','Swing','Fight','TimeUp','Result'];
fs.mkdirSync(path.join(target, '効果音'), {recursive: true});
const settings=fs.readFileSync(path.join(root,'AniBato/Assets/_Project/Data/AudioSettings.asset'),'utf8');
const baseBpm=Number(settings.match(/^    Bpm: (\d+)/m)[1]),bars=Number(settings.match(/^    LoopBeats: (\d+)/m)[1])/4;
const tracks = [
 ['BGM_メニュー.wav','01_紙の舞台、開幕！.wav',baseBpm-12],
 ['BGM_星の終わり.wav','02_青い都市のパルス.wav',baseBpm],
 ['BGM_推し駒.wav','03_駒たちの大立ち回り.wav',baseBpm+8],
 ['BGM_料理の舞台.wav','04_文化祭キッチン・ラッシュ.wav',baseBpm+16]
];
const sha = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
function exportWave(from, to, extra={}) {
 const bytes=fs.readFileSync(path.join(source,from));
 if(bytes.toString('ascii',0,4)!=='RIFF'||bytes.readUInt16LE(22)!==1||bytes.readUInt32LE(24)!==24000||bytes.readUInt16LE(34)!==16)throw Error('Unexpected audio format: '+from);
 const count=bytes.readUInt32LE(40)/2; let peak=0,sum=0;
 for(let n=0;n<count;n++){const s=bytes.readInt16LE(44+n*2)/32768;peak=Math.max(peak,Math.abs(s));sum+=s*s;}
 if(peak>=.9||sum===0)throw Error('Invalid waveform: '+from);
 fs.writeFileSync(path.join(target,to),bytes);
 return {file:to.replaceAll('\\','/'),sampleRate:24000,channels:1,seconds:count/24000,peak,rms:Math.sqrt(sum/count),sha256:sha(bytes),...extra};
}
const report={schemaVersion:1,date:'2026-10-19',implementation:'PAPER_THEATRE_AUDIO_REFRESH',thirdPartyAudio:false,tracks:[],effects:[],source:[]};
for(const [from,to,bpm] of tracks)report.tracks.push(exportWave(from,to,{bpm,bars}));
for(let i=0;i<ids.length;i++)report.effects.push(exportWave('SE_'+ids[i]+'.wav',path.join('効果音',String(i+1).padStart(2,'0')+'_'+cues[i]+'.wav'),{cue:ids[i]}));
const sampler=fs.readdirSync(source).find(f=>f.startsWith('SE_通常_'));
report.sampler=exportWave(sampler,'05_効果音一覧.wav',{order:cues});
for(const file of ['Presentation/PaperAudioSynth.cs','Presentation/PaperMusicComposer.cs','Presentation/PaperSoundEffects.cs','Presentation/ArcadeAudio.cs']){
 const relative='AniBato/Assets/_Project/Scripts/'+file;report.source.push({file:relative,sha256:sha(fs.readFileSync(path.join(root,relative)))});
}
const asset='AniBato/Assets/_Project/Data/AudioSettings.asset';report.source.push({file:asset,sha256:sha(fs.readFileSync(path.join(root,asset)))});
fs.writeFileSync(path.join(target,'音声一覧.json'),JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({tracks:report.tracks,effects:report.effects.length,sampler:report.sampler.seconds},null,2));
